type Livre = { titre: string };
function estLivre(v: unknown): v is Livre {
  return typeof v === "object" && v !== null && typeof (v as Record<string, unknown>).titre === "string";
}

type Resultat<T> = { ok: true; valeur: T } | { ok: false; erreur: string };
function lireAge(texte: string): Resultat<number> {
  const age = Number(texte);
  if (!Number.isInteger(age) || age < 0 || texte.trim() === "")
    return { ok: false, erreur: "âge invalide" };
  return { ok: true, valeur: age };
}
const resultat = lireAge("18");
console.log(resultat.ok ? resultat.valeur + 1 : resultat.erreur);
